nix/direct/rtlil.nix.text:
{ runCommand, yosys, rtl }:
runCommand "tinystories-rtlil" {} ''
  mkdir "$out"
  ${yosys}/bin/yosys -Q -p "
    read_verilog -sv ${rtl}/core.sv ${rtl}/model.sv ${rtl}/memory.sv;
    hierarchy -check -top model_top;
    proc;
    memory_collect;
    opt_dff *model_memory;
    select *;
    flatten -noscopeinfo;
    opt_clean;
    check -assert;
    setattr -set fsm_encoding \"none\" w:*;
    select *;
    write_rtlil $out/model.il
  "
''

nix/direct/prepared.nix.text:
{ runCommand, yosys, rtlil }:
runCommand "tinystories-prepared" {} ''
  mkdir "$out"
  ${yosys}/bin/yosys -Q -p "
    read_rtlil ${rtlil}/model.il;
    prep -top model_top;
    check -assert;
    write_rtlil $out/model.il
  "
''

nix/direct/dsp.nix.text:
{ runCommand, yosys, prepared }:
runCommand "tinystories-dsp" {} ''
  mkdir "$out"
  ${yosys}/bin/yosys -Q -p "
    read_rtlil ${prepared}/model.il;
    synth_xilinx -family xc7 -top model_top -noiopad -noclkbuf -run begin:prepare;
    synth_xilinx -family xc7 -top model_top -noiopad -noclkbuf -run map_dsp:coarse;
    opt_clean;
    check -assert;
    stat -tech xilinx;
    write_rtlil $out/model.il
  "
''

nix/direct/ram.nix.text:
{ runCommand, yosys, dsp }:
runCommand "tinystories-ram" {} ''
  mkdir "$out"
  ${yosys}/bin/yosys -Q -p "
    read_rtlil ${dsp}/model.il;
    submod -name model_memories t:\$mem_v2;
    select *;
    memory -nomap;
    synth_xilinx -family xc7 -top model_top -noiopad -noclkbuf -run map_memory:map_ffram;
    flatten -noscopeinfo;
    check -assert;
    stat -tech xilinx;
    write_rtlil $out/model.il
  "
''
